          <Badge variant="outline">{job.priority}</Badge>
          <Badge variant="outline">{formatLabel(job.status)}</Badge>
        </div>
        <h1 className="mt-3 text-2xl font-semibold text-slate-950">{job.title}</h1>
        <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">{job.summary}</p>
        <Link className="mt-4 inline-flex text-sm font-medium text-blue-700" href={`/workspace/voyages/${job.voyageId}`}>
          Open voyage {job.voyageId}
        </Link>
      </section>

      <JobStatusActions currentStatus={job.status} jobId={job.id} />

      <Card>
        <CardHeader>
          <CardTitle>Evidence</CardTitle>
          <CardDescription>Source trail used to generate this operational job.</CardDescription>
        </CardHeader>
        <CardContent>
          {evidence.length === 0 ? (
            <p className="text-sm text-slate-500">No evidence was attached.</p>
          ) : (
            <div className="space-y-3">
              {evidence.map((item, index) => (
                <div className="rounded-lg border border-slate-200 p-3" key={`${item.sourceType}-${item.sourceId}-${index}`}>
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge variant="outline">{item.sourceType ?? "source"}</Badge>
                    {item.href ? (
                      <Link className="font-medium text-slate-950 hover:text-blue-700" href={item.href}>
                        {item.label ?? item.sourceId}
