                      <span className="font-medium text-slate-950">{item.label ?? item.sourceId}</span>
                    )}
                  </div>
                  {item.excerpt ? <p className="mt-2 text-sm leading-6 text-slate-500">{item.excerpt}</p> : null}
                </div>
              ))}
            </div>
