                    </TableCell>
                    <TableCell className="max-w-sm truncate text-slate-500">{file.error}</TableCell>
                  </TableRow>
                ))}
                {health.failedFiles.length === 0 ? (
                  <TableRow>
                    <TableCell className="h-20 text-center text-sm text-slate-500" colSpan={3}>
                      No failed files.
                    </TableCell>
                  </TableRow>
                ) : null}
              </TableBody>
            </Table>
          </CardContent>
